WITH base AS (SELECT * FROM suppliers WHERE UPPER(TRIM(supplier_name)) = 'SIAM PARTS CO'), city_summary AS (SELECT city, CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.5 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(CASE WHEN city = 'London' THEN rating ELSE 0 END) AS london_rating FROM base GROUP BY city, CASE WHEN rating >= 4.3 THEN 'high' WHEN rating >= 1.5 THEN 'mid' ELSE 'low' END) SELECT * FROM city_summary WHERE london_rating >= 71
